-- Synchronize identity generators after explicit IDs were loaded.
-- This prevents future APEX inserts from attempting to reuse ID 1.
ALTER TABLE DEPARTMENTS MODIFY DEPARTMENT_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE DOCTOR_SPECIALTIES MODIFY SPECIALTY_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE MEDICINE_CATEGORIES MODIFY CATEGORY_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE APPOINTMENT_STATUSES MODIFY STATUS_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE PATIENTS MODIFY PATIENT_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE ROOMS MODIFY ROOM_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE DOCTORS MODIFY DOCTOR_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE MEDICINES MODIFY MEDICINE_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
