ALTER TABLE ADMISSIONS MODIFY ADMISSION_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE PATIENT_VISITS MODIFY VISIT_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE PRESCRIPTIONS MODIFY PRESCRIPTION_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
